                let others = visibleRecord.quests.filter { $0.type != .main }
                ForEach(others) { quest in
                    QuestRowCompact(
                        quest: quest,
                        isHighlighted: isHighlighted(quest.id),
                        onSaveProject: hasProjectLink(sourceId: quest.id.uuidString) ? nil : {
