private struct ManualPrincipleFormSheet: View {
    @EnvironmentObject private var store: AppStore
    @Environment(\.dismiss) private var dismiss
    @State private var title = ""
    @State private var summary = ""
    @State private var triggerContext = ""
    @State private var actionsText = ""
    @State private var successCriteria = ""
    @State private var exceptions = ""
    @State private var isSaving = false
    @State private var errorMessage: String?

    private var canSave: Bool {
        !title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty &&
        !summary.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty &&
        !isSaving
    }

    var body: some View {
        NavigationStack {
            Form {
                Section {
                    TextField("标题 *", text: $title)
                    TextField("摘要 *", text: $summary, axis: .vertical)
                        .lineLimit(2...4)
                } header: {
                    Text("必填")
                }

                Section {
                    TextField("触发场景", text: $triggerContext, axis: .vertical)
                        .lineLimit(2...4)
                    TextField("动作（每行一个）", text: $actionsText, axis: .vertical)
                        .lineLimit(3...6)
                } header: {
                    Text("可选")
                }

                Section {
                    TextField("成功标准", text: $successCriteria, axis: .vertical)
                        .lineLimit(2...4)
                    TextField("例外情况", text: $exceptions, axis: .vertical)
                        .lineLimit(2...4)
                }

                if let error = errorMessage {
                    Section {
                        Text(error)
                            .font(.caption)
                            .foregroundStyle(DS.caution)
                    }
                }
            }
            .navigationTitle("添加原则")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("取消") { dismiss() }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("保存") {
                        Task { await savePrinciple() }
                    }
                    .disabled(!canSave)
                }
            }
            .presentationDetents([.large])
            .presentationDragIndicator(.visible)
        }
    }

    private func savePrinciple() async {
        isSaving = true
        errorMessage = nil
        let lines = actionsText.components(separatedBy: .newlines)
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        let success = await store.addManualPrinciple(
            title: title,
            summary: summary,
            triggerContext: triggerContext,
            actions: lines,
            successCriteria: successCriteria,
            exceptions: exceptions
        )
        isSaving = false
        if success {
            dismiss()
        } else {
            errorMessage = store.todayLoopMessage
        }
    }
}

